def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    separator = next(v for v, _ in counts.most_common() if v != background)

    row_lines = [
        r for r in range(h)
        if sum(grid[r][c] == separator for c in range(w)) / w > 0.65
    ]
    col_lines = [
        c for c in range(w)
        if sum(grid[r][c] == separator for r in range(h)) / h > 0.65
    ]

    def special(v):
        return v != background and v != separator

    active_rows = [
        i for i, r in enumerate(row_lines)
        if any(special(grid[r][c]) for c in col_lines)
    ]
    active_cols = [
        j for j, c in enumerate(col_lines)
        if any(special(grid[r][c]) for r in row_lines)
    ]

    if not active_rows or not active_cols:
        return []

    row_lines = row_lines[active_rows[0]:active_rows[-1] + 1]
    col_lines = col_lines[active_cols[0]:active_cols[-1] + 1]

    out = []
    for r1, r2 in zip(row_lines, row_lines[1:]):
        row = []
        for c1, c2 in zip(col_lines, col_lines[1:]):
            corners = (
                grid[r1][c1], grid[r1][c2],
                grid[r2][c1], grid[r2][c2],
            )
            value = corners[0]
            if not special(value) or any(v != value for v in corners):
                value = background
            row.append(value)
        out.append(row)
    return out
